    <style>*{box-sizing:border-box}:root{--navy:#0f172a;--muted:#64748b;--blue:#2563eb;--blue-dark:#1d4ed8}body{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:linear-gradient(135deg,#b8c9df 0%,#d4e0ed 42%,#c6d8e9 100%);display:grid;place-items:center;min-height:100vh;margin:0;color:var(--navy);position:relative;overflow:hidden}body:before{content:"";position:absolute;width:980px;height:980px;border-radius:50%;background:radial-gradient(circle,rgba(37,99,235,.30) 0%,rgba(59,130,246,.17) 30%,rgba(59,130,246,.06) 55%,rgba(59,130,246,0) 73%);top:-560px;left:-300px;pointer-events:none}body:after{content:"";position:absolute;width:920px;height:920px;border-radius:50%;background:radial-gradient(circle,rgba(14,165,233,.26) 0%,rgba(56,189,248,.14) 32%,rgba(56,189,248,.05) 55%,rgba(56,189,248,0) 74%);bottom:-540px;right:-280px;pointer-events:none}.box{position:relative;z-index:1;background:rgba(255,255,255,.985);backdrop-filter:blur(18px);width:min(410px,calc(100% - 32px));padding:32px;border:1px solid rgba(255,255,255,.92);border-radius:19px;box-shadow:0 36px 90px rgba(15,23,42,.24),0 10px 26px rgba(15,23,42,.12),0 0 0 1px rgba(148,163,184,.16)}.brand{display:flex;align-items:center;gap:10px;margin-bottom:28px}.brand-mark{width:38px;height:38px;border-radius:11px;background:linear-gradient(145deg,#3b82f6,#1d4ed8);color:#fff;display:grid;place-items:center;font-size:17px;font-weight:800;box-shadow:0 9px 20px rgba(37,99,235,.34),0 2px 5px rgba(37,99,235,.18)}.brand-name{font-size:17px;font-weight:750;letter-spacing:-.25px}.subtitle{color:var(--muted);margin:0 0 24px;font-size:14px}h2{font-size:25px;line-height:1.2;margin:0 0 7px;letter-spacing:-.5px}.field{margin-bottom:17px}.label{display:block;margin-bottom:7px;font-size:13px;font-weight:650;color:#334155}.password-wrap{position:relative}.input{width:100%;height:44px;padding:11px 12px;border:1px solid #c7d3e1;border-radius:9px;background:#fff;color:var(--navy);font-size:14px;outline:none;transition:border-color .15s,box-shadow .15s}.input:focus{border-color:var(--blue);box-shadow:0 0 0 3px rgba(37,99,235,.13)}.password-wrap .input{padding-right:72px}.show{position:absolute;right:7px;top:5px;height:34px;border:0;background:transparent;color:var(--blue);font-size:12px;font-weight:700;cursor:pointer;padding:6px 8px}.captcha-box{padding:14px;background:linear-gradient(145deg,#f8fbff,#eef4fb);border:1px solid #cfdae7;border-radius:12px;margin-bottom:13px;box-shadow:inset 0 1px 0 rgba(255,255,255,.9),0 3px 10px rgba(30,64,175,.06)}.captcha-label{display:block;font-size:13px;font-weight:700;color:#334155;margin-bottom:9px}.slider-track{position:relative;height:44px;border-radius:22px;background:linear-gradient(180deg,#e7eef7,#dce6f1);border:1px solid #c4d1df;box-shadow:inset 0 2px 5px rgba(15,23,42,.08),0 1px 0 rgba(255,255,255,.9);touch-action:none;user-select:none;overflow:hidden}.slider-track:before{content:"";position:absolute;left:5px;right:5px;top:5px;height:8px;border-radius:8px;background:rgba(255,255,255,.46);pointer-events:none}.slider-target{position:absolute;top:4px;height:34px;width:34px;border-radius:50%;border:2px dashed #7c91aa;background:rgba(255,255,255,.72);box-shadow:inset 0 0 0 3px rgba(255,255,255,.45);transform:translateX(-50%);pointer-events:none}.slider-fill{position:absolute;left:0;top:0;height:100%;width:0;background:linear-gradient(90deg,#bfdbfe,#93c5fd);box-shadow:inset 0 1px 0 rgba(255,255,255,.5);pointer-events:none;transition:width .08s linear}.slider-thumb{position:absolute;top:4px;left:4px;width:34px;height:34px;border-radius:50%;background:linear-gradient(145deg,#3b82f6,#1d4ed8);border:2px solid rgba(255,255,255,.9);color:#fff;display:grid;place-items:center;font-weight:800;font-size:19px;line-height:1;box-shadow:0 5px 12px rgba(37,99,235,.34),0 2px 4px rgba(15,23,42,.14);cursor:grab;z-index:2;transform:translateX(0)}.slider-thumb.dragging{cursor:grabbing}.slider-success{display:none;text-align:center;color:#166534;font-weight:700;padding-top:8px;font-size:12px}.captcha-box.verified .slider-success{display:block}.captcha-box.verified .slider-track{border-color:#86efac;background:linear-gradient(180deg,#ecfdf5,#dcfce7)}.captcha-box.verified .slider-fill{background:linear-gradient(90deg,#86efac,#4ade80)}.captcha-box.verified .slider-thumb{background:linear-gradient(145deg,#22c55e,#16a34a);box-shadow:0 5px 12px rgba(22,163,74,.28)}.captcha-hint,.security-note{font-size:11px;color:var(--muted);line-height:1.4}.captcha-hint{margin:8px 0 0}.security-note{margin:0 0 16px}.button{width:100%;height:44px;padding:11px;border:0;border-radius:9px;background:linear-gradient(135deg,#2563eb,#1d4ed8);color:#fff;font-size:14px;font-weight:700;cursor:pointer;box-shadow:0 8px 18px rgba(37,99,235,.22)}.links{display:flex;justify-content:center;gap:18px;margin-top:17px}.link{color:#2563eb;text-decoration:none;font-size:13px;font-weight:600}.link:hover{text-decoration:underline}.error,.status{padding:11px 12px;border-radius:9px;margin-bottom:16px;font-size:13px}.error{background:#fef2f2;color:#b91c1c;border:1px solid #fecaca}.status{background:#f0fdf4;color:#166534;border:1px solid #bbf7d0}@media(max-width:480px){body{background:linear-gradient(135deg,#d0dceb 0%,#e1e9f3 48%,#d0e0ed 100%)}.box{padding:26px;width:min(410px,calc(100% - 24px));border-radius:16px}h2{font-size:23px}}
