        <div class="field"><label class="label" for="email">Email</label><input class="input" id="email" type="email" name="email" value="{{ old('email') }}" required autofocus autocomplete="username"></div>
        <div class="field"><label class="label" for="password">Password</label><div class="password-wrap"><input class="input" id="password" type="password" name="password" required autocomplete="current-password"><button class="show" type="button" onclick="togglePassword()">Show</button></div></div>
        <div class="captcha-box" id="captcha-box"><span class="captcha-label">Security check</span><div class="slider-track" id="slider-track" role="slider" aria-label="Slide to complete security check" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0" tabindex="0"><div class="slider-fill" id="slider-fill"></div><div class="slider-target" id="slider-target" style="left:{{ $captchaTarget }}%"></div><div class="slider-thumb" id="slider-thumb">›</div></div><div class="slider-success">✓ Verification complete</div><p class="captcha-hint">Drag the blue button to the circle. Works with mouse or touch.</p><input type="hidden" name="captcha_position" id="captcha_position" value=""></div>
        <p class="security-note">Complete the security check before signing in.</p><button class="button" type="submit">Sign in</button>
    </form>
    <div class="links"><a class="link" href="{{ route('register') }}">Sign up</a><a class="link" href="{{ route('password.request') }}">Forgot password?</a></div>
</div>
<script>
function togglePassword(){const input=document.getElementById('password'),button=document.querySelector('.show'),show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'Hide':'Show'}
(function(){const track=document.getElementById('slider-track'),thumb=document.getElementById('slider-thumb'),fill=document.getElementById('slider-fill'),hidden=document.getElementById('captcha_position'),target=document.getElementById('slider-target'),box=document.getElementById('captcha-box'),targetPosition=parseFloat(getComputedStyle(target).left)/track.getBoundingClientRect().width*100;let dragging=false,verified=false,position=0;function setPosition(x){const r=track.getBoundingClientRect(),max=r.width-thumb.offsetWidth-6;position=Math.max(0,Math.min(100,((x-r.left-thumb.offsetWidth/2-3)/max)*100));thumb.style.transform='translateX('+max*position/100+'px)';fill.style.width=Math.min(100,position+4)+'%';track.setAttribute('aria-valuenow',Math.round(position))}function reset(){position=0;thumb.style.transform='translateX(0)';fill.style.width='0';hidden.value='';track.setAttribute('aria-valuenow','0')}function finish(){if(Math.abs(position-targetPosition)<=8){verified=true;hidden.value=position.toFixed(2);box.classList.add('verified');thumb.textContent='✓';thumb.style.cursor='default'}else reset()}thumb.addEventListener('pointerdown',e=>{if(verified)return;dragging=true;thumb.classList.add('dragging');thumb.setPointerCapture(e.pointerId);setPosition(e.clientX)});thumb.addEventListener('pointermove',e=>{if(dragging&&!verified)setPosition(e.clientX)});thumb.addEventListener('pointerup',()=>{if(!verified){dragging=false;thumb.classList.remove('dragging');finish()}});track.addEventListener('keydown',e=>{if(verified)return;if(['ArrowRight','ArrowUp'].includes(e.key)){e.preventDefault();setPosition(track.getBoundingClientRect().left+track.clientWidth*(Math.min(100,position+5)/100));finish()}if(['ArrowLeft','ArrowDown'].includes(e.key)){e.preventDefault();setPosition(track.getBoundingClientRect().left+track.clientWidth*(Math.max(0,position-5)/100))}});document.getElementById('login-form').addEventListener('submit',e=>{if(!verified){e.preventDefault();alert('Please complete the slider security check.')}})})();
</script>
</body>
